param(
  [switch]$KeepRunning,
  [switch]$ResetLocal
)
$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot
Set-Location $root
function Pass($m){Write-Host "PASS $m"}
function Assert($c,$m){if(!$c){throw $m};Pass $m}
function Native($m){Assert ($LASTEXITCODE-eq0) "$m exit"}
function HttpStatus($uri,$method,$headers,$body){try{$r=Invoke-WebRequest $uri -Method $method -Headers $headers -ContentType application/json -Body $body -UseBasicParsing;[int]$r.StatusCode}catch{if($_.Exception.Response){[int]$_.Exception.Response.StatusCode}else{throw}}}
function ChunkedStatus($uri,$headers,$body){$r=[Net.HttpWebRequest]::Create($uri);$r.Method='POST';$r.ContentType='application/json';$r.SendChunked=$true;foreach($h in $headers.GetEnumerator()){$r.Headers.Add($h.Key,$h.Value)};$b=[Text.Encoding]::UTF8.GetBytes($body);$s=$r.GetRequestStream();try{$s.Write($b,0,$b.Length)}finally{$s.Dispose()};try{$x=$r.GetResponse();try{[int]$x.StatusCode}finally{$x.Dispose()}}catch [Net.WebException]{if($_.Exception.Response){$x=$_.Exception.Response;try{[int]$x.StatusCode}finally{$x.Dispose()}}else{throw}}}
function MetaHeaders($body,$secret){$h=[Security.Cryptography.HMACSHA256]::new([Text.Encoding]::UTF8.GetBytes($secret));try{$digest=($h.ComputeHash([Text.Encoding]::UTF8.GetBytes($body))|% ToString x2)-join''}finally{$h.Dispose()};@{'x-hub-signature-256'="sha256=$digest"}}
$generated=Join-Path $root '.generated'
$localEnvFile=Join-Path $root '.env'
$envFile=Join-Path $generated 'runtime.env'
$failure=$null;$cleanupFailure=$null;$managedEnvironment=$false;$lockAcquired=$false
$mutex=[Threading.Mutex]::new($false,'Local\N8NSalesFlowAIHarness')
try {
  # ponytail: one lock per Windows login session; use a checkout-scoped mutex if parallel clones matter.
  $lockAcquired=$mutex.WaitOne(0);if(-not$lockAcquired){throw 'Another SalesFlow harness is already running.'}
  if($ResetLocal-and-not$KeepRunning){throw '-ResetLocal requires -KeepRunning.'}
  docker info *> $null;Native 'Docker readiness'
  $composeProject=(docker compose --env-file .env.example config --format json|ConvertFrom-Json).name;Native 'compose project resolution'
  $existingVolumes=@(docker volume ls --filter "label=com.docker.compose.project=$composeProject" -q);Native 'local volume inventory'
  $localEnvExists=Test-Path $localEnvFile
  if(($localEnvExists-or$existingVolumes)-and-not$ResetLocal){$recovery=if($localEnvExists-and$existingVolumes){'Resume with docker compose --env-file .env up -d'}else{'The local environment is incomplete'};throw "$recovery. Replace it explicitly with -KeepRunning -ResetLocal."}
  $manifest=Get-Content release/release-manifest.json -Raw|ConvertFrom-Json
  $workflows=@(Get-ChildItem workflows -Filter *.json|Sort-Object Name);Assert ($workflows.Count-eq7) 'seven workflows'
  $configs=@(Get-ChildItem config -Filter *.json|Sort-Object Name);Assert ((Compare-Object @($configs.Name) @($manifest.configFiles)).Count-eq0) 'exact config file set'
  Assert ((Compare-Object @($workflows.Name) @($manifest.workflowFiles)).Count-eq0) 'exact workflow file set'
  $releaseSet=Get-Content config/release-set.json -Raw|ConvertFrom-Json;Assert ($releaseSet.reviewedManifestHash-eq$manifest.activationManifestSha256-and$releaseSet.manifestVersion-eq$manifest.activationManifest.version-and$releaseSet.policyVersion-eq$manifest.activationManifest.policyVersion-and$releaseSet.knowledgeVersion-eq$manifest.activationManifest.knowledgeVersion) 'exact activation manifest binding';foreach($p in $manifest.activationManifest.inputHashes.psobject.Properties){Assert ($manifest.inputHashes.($p.Name)-eq$p.Value) "activation input $($p.Name)"}
  $types=@();foreach($f in $workflows){$w=Get-Content $f.FullName -Raw|ConvertFrom-Json;$types+=$w.nodes.type;Assert ($w.settings.saveDataSuccessExecution-eq'none'-and$w.settings.saveDataErrorExecution-eq'none'-and!$w.settings.saveManualExecutions) "$($f.Name) persistence disabled"}
  Assert ((Compare-Object @($types|Sort-Object -Unique) @($manifest.nodeTypes)).Count-eq0) 'approved native nodes exact'
  $w5=Get-Content workflows/05-follow-up-scheduler.json -Raw;Assert ($w5-match'scheduleTrigger'-and$w5-match'schedule_work'-and$w5-match'salesflow-wf-03'-and$w5-match'salesflow-wf-06') 'UTC scheduler chains durable workers'
  Assert (-not((Get-Content workflows/03-outbox-dispatcher.json,workflows/06-handoff-dispatcher.json -Raw)-match'body\.outcome')) 'internal adapter outcomes'
  foreach($p in $manifest.inputHashes.psobject.Properties){Assert ((Get-FileHash $p.Name -Algorithm SHA256).Hash.ToLower()-eq$p.Value) "manifest input $($p.Name)"}
  $ids=(Get-Content tests/pilot-scenarios.json -Raw|ConvertFrom-Json).scenarios;$sql=Get-Content tests/runtime.sql -Raw
  foreach($id in $ids){Assert ($sql-match"INSERT INTO evidence[^;]*\('$id'\)") "$id asserted before marker"}
  if($ResetLocal){
    $oldEnvFile=if($localEnvExists){$localEnvFile}else{Join-Path $root '.env.example'}
    $ErrorActionPreference='Continue'
    docker compose --env-file $oldEnvFile down -v --remove-orphans *> $null;Native 'existing local reset'
    $remaining=@(docker volume ls --filter "label=com.docker.compose.project=$composeProject" -q);Native 'reset volume inventory';Assert (-not$remaining) 'existing local volumes removed'
    Remove-Item $localEnvFile -Force -ErrorAction SilentlyContinue
    $ErrorActionPreference='Stop'
  }
  $managedEnvironment=$true
  Remove-Item $generated -Recurse -Force -ErrorAction SilentlyContinue;New-Item $generated -ItemType Directory|Out-Null;New-Item (Join-Path $generated exported) -ItemType Directory|Out-Null
  $scheduler=[guid]::NewGuid().ToString('N')+[guid]::NewGuid().ToString('N');$encryption=[guid]::NewGuid().ToString('N')+[guid]::NewGuid().ToString('N');$super=[guid]::NewGuid().ToString('N');$owner=[guid]::NewGuid().ToString('N');$n8ndb=[guid]::NewGuid().ToString('N');$workflowdb=[guid]::NewGuid().ToString('N');$metaRuntime=[guid]::NewGuid().ToString('N')+[guid]::NewGuid().ToString('N');$metaSecret=[guid]::NewGuid().ToString('N')+[guid]::NewGuid().ToString('N');$metaVerify=[guid]::NewGuid().ToString('N')
  $envText=(Get-Content .env.example -Raw)-replace'(?m)^SCHEDULER_TOKEN=.*$',"SCHEDULER_TOKEN=$scheduler"-replace'(?m)^N8N_ENCRYPTION_KEY=.*$',"N8N_ENCRYPTION_KEY=$encryption"-replace'(?m)^POSTGRES_SUPERUSER_PASSWORD=.*$',"POSTGRES_SUPERUSER_PASSWORD=$super"-replace'(?m)^MIGRATION_PASSWORD=.*$',"MIGRATION_PASSWORD=$owner"-replace'(?m)^N8N_DB_PASSWORD=.*$',"N8N_DB_PASSWORD=$n8ndb"-replace'(?m)^WORKFLOW_DB_PASSWORD=.*$',"WORKFLOW_DB_PASSWORD=$workflowdb"-replace'(?m)^META_ACCOUNT_REF=.*$',"META_ACCOUNT_REF=test-account"-replace'(?m)^META_WABA_ID=.*$',"META_WABA_ID=test-waba"-replace'(?m)^META_PHONE_NUMBER_ID=.*$',"META_PHONE_NUMBER_ID=test-phone"-replace'(?m)^META_VERIFY_TOKEN=.*$',"META_VERIFY_TOKEN=$metaVerify"-replace'(?m)^META_RUNTIME_TOKEN=.*$',"META_RUNTIME_TOKEN=$metaRuntime"
  [IO.File]::WriteAllText($envFile,$envText,[Text.UTF8Encoding]::new($false))
  $ErrorActionPreference='Continue'
  docker compose --env-file $envFile down -v --remove-orphans *> $null;Native 'initial cleanup'
  docker compose --env-file $envFile up -d postgres --wait *> $null;Native 'postgres readiness'
  $migration=(Get-Content database/001-initial.sql -Raw)-replace'__MIGRATION_PASSWORD__',$owner-replace'__WORKFLOW_DB_PASSWORD__',$workflowdb-replace'__N8N_DB_PASSWORD__',$n8ndb
  1..2|%{$migration|docker compose --env-file $envFile exec -T postgres psql -U postgres -d salesflow -v ON_ERROR_STOP=1 *> $null;Native "migration $_"}
  $rt=[guid]::NewGuid().ToString('N')+[guid]::NewGuid().ToString('N');$rt2=[guid]::NewGuid().ToString('N')+[guid]::NewGuid().ToString('N');$op=[guid]::NewGuid().ToString('N')+[guid]::NewGuid().ToString('N');$op2=[guid]::NewGuid().ToString('N')+[guid]::NewGuid().ToString('N')
  $account=Get-Content config/account.json -Raw|ConvertFrom-Json;Assert ($account.accountRef-eq'test-account') 'account config drives fixture';$accountEnabled=if($account.enabled){'true'}else{'false'}
  @"
SET search_path=salesflow,public;INSERT INTO accounts VALUES('$($account.accountRef)',$accountEnabled),('account-b',true);
SELECT bootstrap('$rt','runtime','runtime-a','test-account');SELECT bootstrap('$rt2','runtime','runtime-b','account-b');SELECT bootstrap('$metaRuntime','runtime','meta-runtime','test-account');SELECT bootstrap('$op','operator','operator-a','test-account');SELECT bootstrap('$op2','operator','operator-b','account-b');SELECT bootstrap('$scheduler','scheduler','scheduler',NULL);
INSERT INTO controls VALUES('test-account','stop','{"enabled":false}'),('account-b','stop','{"enabled":false}');
"@|docker compose --env-file $envFile exec -T postgres psql -U postgres -d salesflow -v ON_ERROR_STOP=1 *> $null;Native 'account bootstrap'
  function ConfigJson($query,$label){$out=$query|docker compose --env-file $envFile exec -T postgres psql -U postgres -d salesflow -v ON_ERROR_STOP=1 -qAt;Native "$label query";$r=$out|ConvertFrom-Json;Assert ($null-ne$r-and$r.ok) "$label ok";$r}
  $priorReleaseJson='{"accountRef":"test-account","kind":"release_set","version":"release-v2","reviewedManifestHash":"d629a589bbd4a24b3e1bf063559ea29e53720811a2bd5ca8c5da9cea979b09ac","policyVersion":"policy-v1","knowledgeVersion":"knowledge-v1","manifestVersion":"release-v2"}';$r=ConfigJson "SELECT salesflow.save_config('$op','$priorReleaseJson'::jsonb);" 'save existing release v2';Assert $r.created 'release v2 fixture created';$r=ConfigJson "SELECT salesflow.activate_config('$op','test-account','release_set','release-v2',NULL);" 'activate existing release v2';Assert $r.activated 'release v2 fixture activated'
  foreach($f in Get-ChildItem config -Filter *.json|? Name -ne account.json){$j=Get-Content $f.FullName -Raw;$q=$j-replace"'","''";$b=$j|ConvertFrom-Json;$r=ConfigJson "SELECT salesflow.save_config('$op','$q');" "save $($f.Name) a";Assert $r.created "$($f.Name) a created";$expected=if($b.kind-eq'release_set'){"'release-v2'"}else{'NULL'};$r=ConfigJson "SELECT salesflow.activate_config('$op','$($b.accountRef)','$($b.kind)','$($b.version)',$expected);" "activate $($f.Name) a";Assert $r.activated "$($f.Name) a activated";$b.accountRef='account-b';$q=(($b|ConvertTo-Json -Compress -Depth 20)-replace"'","''");$r=ConfigJson "SELECT salesflow.save_config('$op2','$q');" "save $($f.Name) b";Assert $r.created "$($f.Name) b created";$r=ConfigJson "SELECT salesflow.activate_config('$op2','account-b','$($b.kind)','$($b.version)',NULL);" "activate $($f.Name) b";Assert $r.activated "$($f.Name) b activated"}
  $releaseUpgrade=docker compose --env-file $envFile exec -T postgres psql -U postgres -d salesflow -Atc "SELECT count(*)||':'||max(version)FILTER(WHERE active)FROM salesflow.config_docs WHERE account_ref='test-account'AND kind='release_set'";Native 'release upgrade query';Assert ($releaseUpgrade.Trim()-eq'2:release-v3') 'release set upgrades v2 to active v3'
  $priv=docker compose --env-file $envFile exec -T postgres psql -U postgres -d salesflow -Atc "SELECT has_table_privilege('salesflow_runtime','salesflow.auth_tokens','INSERT')||':'||has_table_privilege('salesflow_runtime','salesflow.audit_events','UPDATE')";Native 'privilege query';Assert ($priv.Trim()-eq'false:false') 'least privilege runtime'
  $priv=docker compose --env-file $envFile exec -T postgres psql -U postgres -d salesflow -Atc "SELECT has_function_privilege('salesflow_runtime','salesflow.ingest_core(text,jsonb,boolean)','EXECUTE')::text";Native 'ingest core privilege query';Assert ($priv.Trim()-eq'false') 'runtime cannot execute private ingest core'
  $activationJson=$manifest.activationManifest|ConvertTo-Json -Compress -Depth 30;$activationB64=[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($activationJson));$activationHash=$manifest.activationManifestSha256;Get-Content tests/runtime.sql -Raw|docker compose --env-file $envFile exec -T postgres psql -U postgres -d salesflow -v ON_ERROR_STOP=1 -v runtime_token=$rt -v runtime_token_2=$rt2 -v operator_token=$op -v scheduler_token=$scheduler -v activation_manifest_b64=$activationB64 -v activation_manifest_hash=$activationHash > (Join-Path $generated runtime.txt);Native 'runtime SQL'
  $line=Get-Content (Join-Path $generated runtime.txt)|?{$_-like'SCENARIOS=*'}|Select-Object -Last 1;Assert ((Compare-Object @($ids|Sort-Object) @(($line-replace'^SCENARIOS=','')-split','|Sort-Object)).Count-eq0) 'S01-S26 exact'
  $jobScript={param($cwd,$ef,$query)Set-Location $cwd;$out=$query|docker compose --env-file $ef exec -T postgres psql -U postgres -d salesflow -v ON_ERROR_STOP=1 -qAt 2>&1;if($LASTEXITCODE-ne0){throw "native psql failed: $out"};$out}
  function Race($queries,$label){$jobs=@($queries|%{Start-Job -ScriptBlock $jobScript -ArgumentList $root,$envFile,$_});$jobs|Wait-Job|Out-Null;foreach($j in $jobs){Assert ($j.State-eq'Completed') "$label worker native exit"};$jobs|Receive-Job|Out-Null;$jobs|Remove-Job}
  Race @(1..6|%{"SET search_path=salesflow,public;SELECT ingest('$rt',jsonb_build_object('account_ref','test-account','provider_id','parallel-replay','contact_ref','parallel','body','hello'));"}) 'replay'
  $n=docker compose --env-file $envFile exec -T postgres psql -U postgres -d salesflow -Atc "SELECT count(*) FROM salesflow.inbound_messages WHERE provider_id='parallel-replay'";Native 'replay count';Assert ($n.Trim()-eq'1') 'parallel replay one row'
  Race @(1..6|%{$body=if($_%2){'one'}else{'two'};"SET search_path=salesflow,public;SELECT ingest('$rt',jsonb_build_object('account_ref','test-account','provider_id','parallel-conflict','contact_ref','parallel-conflict','body','$body'));"}) 'conflicting replay'
  $n=docker compose --env-file $envFile exec -T postgres psql -U postgres -d salesflow -Atc "SELECT count(*) FROM salesflow.inbound_messages WHERE provider_id='parallel-conflict'";Native 'conflicting replay count';Assert ($n.Trim()-eq'1') 'conflicting replay one row'
  $out="SET search_path=salesflow,public;SELECT ingest('$rt',jsonb_build_object('account_ref','test-account','provider_id','parallel-conflict','contact_ref','parallel-conflict','body',CASE WHEN(SELECT body FROM salesflow.inbound_messages WHERE provider_id='parallel-conflict')='one'THEN'two'ELSE'one'END))->>'reason';"|docker compose --env-file $envFile exec -T postgres psql -U postgres -d salesflow -At;Native 'conflicting replay verdict';Assert ($out.Trim()-eq'idempotency_conflict') 'conflicting replay rejected'
  Race @(1..6|%{"SET search_path=salesflow,public;SELECT ingest('$rt',jsonb_build_object('account_ref','test-account','provider_id','parallel-seq-$_','contact_ref','parallel-seq','body','hello'));"}) 'sequence'
  $n=docker compose --env-file $envFile exec -T postgres psql -U postgres -d salesflow -Atc "SELECT count(*)||':'||count(DISTINCT seq) FROM salesflow.inbound_messages WHERE provider_id LIKE'parallel-seq-%'";Native 'sequence count';Assert ($n.Trim()-eq'6:6') 'parallel sequence unique'
  $raceA='{"accountRef":"test-account","kind":"qualification","version":"qualification-race-a","minimumScore":1,"handoffScore":5}';$raceB='{"accountRef":"test-account","kind":"qualification","version":"qualification-race-b","minimumScore":1,"handoffScore":5}';$r=ConfigJson "SELECT salesflow.save_config('$op','$raceA');" 'save activation race a';Assert $r.created 'activation race a created';$r=ConfigJson "SELECT salesflow.save_config('$op','$raceB');" 'save activation race b';Assert $r.created 'activation race b created';$lockQuery="BEGIN;SELECT pg_advisory_xact_lock(hashtextextended('test-account:qualification',0));SELECT pg_sleep(2);SELECT salesflow.activate_config('$op','test-account','qualification','qualification-race-a','qualification-v1');COMMIT;";$lockJob=Start-Job -ScriptBlock $jobScript -ArgumentList $root,$envFile,$lockQuery;$locked=$false;for($i=0;$i-lt20;$i++){$n=docker compose --env-file $envFile exec -T postgres psql -U postgres -d salesflow -Atc "SELECT NOT pg_try_advisory_xact_lock(hashtextextended('test-account:qualification',0))";Native 'activation lock poll';if($n.Trim()-eq't'){$locked=$true;break};Start-Sleep -Milliseconds 100};Assert $locked 'activation race exact lock held';$contender=Start-Job -ScriptBlock $jobScript -ArgumentList $root,$envFile,"SELECT salesflow.activate_config('$op','test-account','qualification','qualification-race-b','qualification-v1');";$jobs=@($lockJob,$contender);$jobs|Wait-Job|Out-Null;foreach($j in $jobs){Assert ($j.State-eq'Completed') 'config activation worker native exit'};$raceJson=@($jobs|Receive-Job|?{$_-match'^\{'}|%{$_|ConvertFrom-Json});$jobs|Remove-Job;Assert (@($raceJson|? ok).Count-eq1-and@($raceJson|? reason -eq stale_active_version).Count-eq1) 'activation race one winner and one stale';$n=docker compose --env-file $envFile exec -T postgres psql -U postgres -d salesflow -Atc "SELECT count(*)||':'||(SELECT count(*)FROM salesflow.audit_events WHERE account_ref='test-account'AND event='config_activated'AND details->>'targetVersion'LIKE'qualification-race-%')FROM salesflow.config_docs WHERE account_ref='test-account'AND kind='qualification'AND active AND version LIKE'qualification-race-%'";Native 'activation race evidence';Assert ($n.Trim()-eq'1:1') 'activation race one active and one audit';$active=docker compose --env-file $envFile exec -T postgres psql -U postgres -d salesflow -Atc "SELECT version FROM salesflow.config_docs WHERE account_ref='test-account'AND kind='qualification'AND active";Native 'activation race winner query';$r=ConfigJson "SELECT salesflow.activate_config('$op','test-account','qualification','qualification-v1','$($active.Trim())');" 'activation race rollback';Assert $r.activated 'activation race rolled back'
  $credential=ConvertTo-Json -InputObject @(@{id='salesflow-postgres-local';name='SalesFlow PostgreSQL';type='postgres';data=@{host='postgres';database='salesflow';user='salesflow_runtime';password=$workflowdb;port=5432;ssl='disable'}},@{id='salesflow-meta-hmac-local';name='SalesFlow Meta HMAC';type='crypto';data=@{hmacSecret=$metaSecret}}) -Depth 6
  [IO.File]::WriteAllText((Join-Path $generated credentials.json),$credential,[Text.UTF8Encoding]::new($false))
  docker compose --env-file $envFile up -d n8n *> $null;Native 'n8n start'
  $ready=$false;for($i=0;$i-lt60;$i++){try{$null=Invoke-WebRequest http://127.0.0.1:5678/healthz -UseBasicParsing -TimeoutSec 2;$ready=$true;break}catch{Start-Sleep 2}};Assert $ready 'bounded n8n readiness'
