  $exportText=(Get-ChildItem (Join-Path $generated exported)-File|Get-Content -Raw)-join'';foreach($secret in @($rt,$rt2,$metaRuntime,$metaSecret,$metaVerify,$op,$op2,$scheduler,$super,$owner,$n8ndb,$workflowdb)){Assert (-not$exportText.Contains($secret)) 'export secret scan'}
  $rh=@{'x-salesflow-token'=$rt};$oh=@{'x-salesflow-token'=$op};$sh=@{'x-salesflow-token'=$scheduler};$base='http://127.0.0.1:5678/webhook/salesflow'
