  $limitBody=MetaEnvelope @(@{id='meta-limit';from='meta-limit';timestamp=$metaTime;type='text';text=@{body='hello'}});$limitObject=$limitBody|ConvertFrom-Json;$limitObject|Add-Member padding '';do{$baseLimit=$limitObject|ConvertTo-Json -Compress -Depth 12;$need=262144-[Text.Encoding]::UTF8.GetByteCount($baseLimit);$limitObject.padding='a'*([Math]::Max(0,$limitObject.padding.Length+$need))}while($need-ne0);$limitBody=$limitObject|ConvertTo-Json -Compress -Depth 12;Assert ([Text.Encoding]::UTF8.GetByteCount($limitBody)-eq262144) 'Meta exact payload fixture';Assert ((HttpStatus "$base/meta" Post (MetaHeaders $limitBody $metaSecret) $limitBody)-eq200) 'Meta exact payload accepted';$overBody=$limitBody+' ';Assert ((HttpStatus "$base/meta" Post (MetaHeaders $overBody $metaSecret) $overBody)-eq400) 'Meta over-limit rejected';$chunkedBody=$limitBody+'  ';Assert ((ChunkedStatus "$base/meta" (MetaHeaders $chunkedBody $metaSecret) $chunkedBody)-eq400) 'Meta measured over-limit chunked body rejected'
